{
  "name": "SocketCAN 多速率周期发送任务",
  "name_en": "SocketCAN Multi-Rate Cyclic Send Task",
  "manufacturer": "",
  "description": "这是一个基于 SocketCAN 的 CAN 总线周期发送任务，用于按固定周期或多速率方式重复发送 CAN 报文。它支持设置发送持续时间、在任务运行中修改报文数据，以及停止后再次启动，常用于实验设备之间的 CAN 通信测试、自动控制和报文注入。",
  "description_en": "This is a SocketCAN-based CAN bus cyclic transmission task used to repeatedly send CAN messages at a fixed cycle or multiple rates. It supports setting a transmission duration, modifying message data while configured, and stopping then restarting the task. It is commonly used for CAN communication testing, automated control, and message injection between laboratory devices.",
  "actions": [
    {
      "action_name": "stop",
      "description": "停止周期发送任务。",
      "description_en": "Stop the cyclic transmission task."
    },
    {
      "action_name": "modify_data",
      "description": "修改周期发送任务使用的报文数据。",
      "description_en": "Modify the message data used by the cyclic transmission task."
    },
    {
      "action_name": "start",
      "description": "启动或重新启动周期发送任务。",
      "description_en": "Start or restart the cyclic transmission task."
    }
  ],
  "tag_hints": [
    "CAN bus",
    "SocketCAN",
    "cyclic message transmission",
    "periodic frame injection",
    "message data update",
    "bus communication testing"
  ]
}

